//! Golden-corpus runner — the native half of tempura's determinism gate.
//!
//! Each `corpus/<case>/` directory holds:
//!
//!   - a pinned input: `song.mid` or `song.it` (GENERATED by `zig build
//!     fixtures` from `tools/gen_fixtures.zig` and COMMITTED, so the
//!     bytes a golden describes are in the tree beside it), or
//!     `doc.sjon` (a timeline document — 10b's half);
//!   - `times.sjon` — the harness: an ordered script of directives,
//!     validated against `schema/tempura-corpus.sjon`;
//!   - `expected.sjon` — the GENERATED golden, one canonical text.
//!
//! `zig build corpus -- --update` regenerates the goldens; the diff is
//! reviewed, and a golden is never hand-edited. This runner is the
//! AUTHORITY for that text: the wasm half re-derives the same bytes and
//! compares against the same goldens, which is where native-vs-wasm
//! equality is asserted (pacer's rule verbatim).
//!
//! ## The harness
//!
//! Hand-authored, VALIDATED against the corpus manifest — a second
//! preloaded bundle, `Schema.loadCorpus`, never composed with the
//! timeline one. Directives run in DOCUMENT ORDER:
//!
//!     (read)                  ; what the core made of the bytes
//!     (roundtrip)             ; rungs 1 and 2 of plan 09's ladder
//!     (walk :max-rows 3)      ; the IT timing walk's RowMap
//!     (write :format0 true)   ; the canonical writer's own output
//!
//! The split is pacer's: SHAPE is the schema's, and what stays here is
//! what a form-at-a-time schema cannot see — document order, which verbs
//! a case's fixture makes meaningful, and "at least one directive".
//!
//! Every other directive the manifest declares (`at`, `snap`, `plan`,
//! `export-score`, `timing`, `build`, `dump`) belongs to P107's documents
//! half: meeting one is `UNRUN <directive>` and a FAILED case. An unrun
//! case is never reported green.
//!
//! ## The golden
//!
//! Canonical down to the byte. The header line names the verb that wrote
//! it, then the fixture is pinned by length and hash — so a fixture that
//! drifts moves every golden that describes it — and then one form per
//! directive, in the order the harness spelled them:
//!
//!     ; tempura corpus golden — GENERATED by `zig build corpus -- --update`; do not hand-edit.
//!     (fixture :file "song.mid" :bytes 74 :sha256 "…")
//!     (read
//!       (smf :format 0 :division 96 :smpte none :tracks 1 :events 4 :running-status 0 :foreign 0)
//!       (diag :code 26 :severity info :start 22 :end 28 :message "…"))
//!     (roundtrip
//!       (rung1 :ok true :sha256 "…")
//!       (rung2 :ok true))
//!     (write :format0 true :sha256 "…" :bytes 74 :tracks 1 :events 9)
//!
//! An `.it` case reads the same way with `(it :title … :speed … :tempo …
//! :orders N :patterns N :instruments N :samples N :message-len N :tmpu
//! B)` in place of the `(smf …)` child, answers `(write …)` with the
//! module's own counts (`:format0` is the SMF merge and is refused), and
//! adds the walk:
//!
//!     (walk :max-rows 1048576
//!       (row :order 0 :pattern 0 :row 0 :start 0 :ticks 6)
//!       (segment :tick 0 :tempo 125)
//!       (onset :ch 0 :tick 0 :note 60)
//!       (total :ticks 24 :loop-row 0))
//!
//! Diagnostics carry the NUMERIC code (the ordinal is the wire, and
//! `zig build audit-diagnostics` is what keeps a code's NAME in a test),
//! the severity, the span into the bytes that were read, and the message
//! verbatim. A row map echoes at most 4096 rows and 4096 onsets and then
//! says how many it left out, so a runaway case cannot produce a golden
//! nobody can read.
//!
//! `(rung1 :ok true)` is `write(read(bytes)) == bytes` and holds for
//! every file tempura's own canonical writer produced; `(rung2 :ok true)`
//! is `read(write(read(bytes)))` equal to `read(bytes)` event for event
//! (`.mid`) or field for field with every pass-through region byte-equal
//! (`.it`). A case whose fixture is deliberately NOT canonical — a SMPTE
//! division the writer never spells, a command byte no IT effect names —
//! carries `(read)` and `(write)` instead, and says why in its
//! `times.sjon`: the hash of what the writer DOES make of it pins the
//! normalisation that rung 1 cannot.
//!
//! Per-case defects (a missing file, a malformed harness, a directive the
//! fixture cannot answer) fail the case and the run continues —
//! collection over abort, the SJON discipline. Only resource exhaustion
//! aborts.

const std = @import("std");
const sjon = @import("sjon");
const Diag = @import("Diag.zig");
const Schema = @import("Schema.zig");
const smf = @import("smf/smf.zig");
const itf = @import("itf/itf.zig");

const Io = std.Io;
const Allocator = std.mem.Allocator;
const Ast = sjon.Ast;
const NodeIndex = Ast.NodeIndex;
const Sha256 = std.crypto.hash.sha2.Sha256;

/// This module's error set: rendering a golden can only fail the way any
/// allocation fails. Everything a case gets wrong is a report line.
pub const Error = error{OutOfMemory};

/// Corpus inputs are small: a harness is a page of text and a fixture is
/// a few kilobytes. Anything bigger is a mistake, not a corpus case.
const MAX_FILE_BYTES: usize = 1 << 20;

/// How many rows and onsets a walk echo carries before it elides the
/// rest. A runaway case plays a million rows; a golden nobody can read
/// is not evidence.
const MAX_ROWS_ECHOED: usize = 4096;
const MAX_ONSETS_ECHOED: usize = 4096;

const GENERATED_HEADER =
    "; tempura corpus golden — GENERATED by `zig build corpus -- --update`; do not hand-edit.\n";

pub fn main(init: std.process.Init) !u8 {
    const arena = init.arena.allocator();
    const gpa = init.gpa;
    const io = init.io;

    var stderr_buf: [4096]u8 = undefined;
    var stderr_file = Io.File.stderr();
    var stderr_writer = stderr_file.writer(io, &stderr_buf);
    const out = &stderr_writer.interface;
    defer out.flush() catch {};

    const args = try init.minimal.args.toSlice(arena);
    var corpus_path: ?[]const u8 = null;
    var update = false;
    for (args[1..]) |arg| {
        if (std.mem.eql(u8, arg, "--update")) {
            update = true;
        } else if (corpus_path == null) {
            corpus_path = arg;
        } else {
            try out.print("usage: corpus-runner <corpus-dir> [--update]\n", .{});
            return 2;
        }
    }
    const root = corpus_path orelse {
        try out.print("usage: corpus-runner <corpus-dir> [--update]\n", .{});
        return 2;
    };

    // Collect case directories, sorted — filesystem iteration order is
    // unspecified and the report has to be stable.
    var dir = Io.Dir.cwd().openDir(io, root, .{ .iterate = true }) catch |err| {
        try out.print("corpus: cannot open `{s}`: {s}\n", .{ root, @errorName(err) });
        return 1;
    };
    defer dir.close(io);
    var names: std.ArrayList([]const u8) = .empty;
    var it = dir.iterate();
    while (try it.next(io)) |entry| {
        if (entry.kind != .directory) continue;
        if (entry.name.len == 0 or entry.name[0] == '.') continue;
        try names.append(arena, try arena.dupe(u8, entry.name));
    }
    std.mem.sort([]const u8, names.items, {}, struct {
        fn lessThan(_: void, a: []const u8, b: []const u8) bool {
            return std.mem.lessThan(u8, a, b);
        }
    }.lessThan);
    if (names.items.len == 0) {
        // The corpus IS the gate: an empty one means the checkout is
        // broken, not that there is nothing to disagree about.
        try out.print("corpus: no cases under `{s}`\n", .{root});
        return 1;
    }

    // One preloaded harness bundle for the whole walk — the manifest is
    // parsed and aggregate-validated once, not once per case, and it
    // outlives every case's validation result.
    var harness_schema = try Schema.loadCorpus(gpa);
    defer harness_schema.deinit();

    var failed: usize = 0;
    var updated: usize = 0;
    for (names.items) |name| {
        switch (try runCase(gpa, &harness_schema, io, out, root, name, update)) {
            .ok => {},
            .updated => updated += 1,
            .failed => failed += 1,
        }
    }

    if (update) {
        try out.print("corpus: {d} case(s), {d} regenerated, {d} failed\n", .{ names.items.len, updated, failed });
    } else {
        try out.print("corpus: {d} case(s), {d} failed\n", .{ names.items.len, failed });
    }
    return if (failed == 0) 0 else 1;
}

const Outcome = enum { ok, updated, failed };

fn runCase(
    gpa: Allocator,
    harness_schema: *const Schema,
    io: Io,
    out: *Io.Writer,
    root: []const u8,
    name: []const u8,
    update: bool,
) !Outcome {
    // Everything this case allocates dies together.
    var case_arena = std.heap.ArenaAllocator.init(gpa);
    defer case_arena.deinit();
    const a = case_arena.allocator();

    const harness_src = readCaseFile(a, io, out, root, name, "times.sjon") orelse return .failed;
    const directives = (try parseHarness(a, gpa, harness_schema, out, name, harness_src)) orelse return .failed;
    const fixture = (try findFixture(a, io, out, root, name)) orelse return .failed;

    var aw: Io.Writer.Allocating = .init(a);
    defer aw.deinit();
    const rep: Report = .{ .out = out, .name = name };
    if (!try renderCase(gpa, a, &aw.writer, fixture, directives, rep)) return .failed;
    const actual = aw.toOwnedSlice() catch return error.OutOfMemory;

    const expected_path = try std.fs.path.join(a, &.{ root, name, "expected.sjon" });
    if (update) {
        Io.Dir.cwd().writeFile(io, .{ .sub_path = expected_path, .data = actual }) catch |err| {
            try out.print("corpus: {s}: cannot write expected.sjon: {s}\n", .{ name, @errorName(err) });
            return .failed;
        };
        try out.print("corpus: {s}: regenerated\n", .{name});
        return .updated;
    }

    const expected = readCaseFile(a, io, out, root, name, "expected.sjon") orelse return .failed;
    const diff = firstDifference(expected, actual) orelse return .ok;
    try reportMismatch(out, name, diff);
    return .failed;
}

fn readCaseFile(
    a: Allocator,
    io: Io,
    out: *Io.Writer,
    root: []const u8,
    name: []const u8,
    file: []const u8,
) ?[:0]u8 {
    const path = std.fs.path.join(a, &.{ root, name, file }) catch |err| {
        out.print("corpus: {s}: cannot join path for {s}: {s}\n", .{ name, file, @errorName(err) }) catch {};
        return null;
    };
    return Io.Dir.cwd().readFileAllocOptions(io, path, a, .limited(MAX_FILE_BYTES), .of(u8), 0) catch |err| {
        out.print("corpus: {s}: cannot read {s}: {s}\n", .{ name, file, @errorName(err) }) catch {};
        return null;
    };
}

// ---------------------------------------------------------------------------
// The fixture
// ---------------------------------------------------------------------------

/// Which core reads a case's fixture. The file name chooses it.
const FixtureKind = enum { smf, it };

/// The case's pinned input: which file it came from, and its bytes.
const Fixture = struct {
    file: []const u8,
    bytes: []const u8,
    kind: FixtureKind,
};

/// The three names a case's input may carry, in the order they are
/// looked for. `doc.sjon` is a timeline document and belongs to P107's
/// documents half, so a case that carries one is UNRUN rather than
/// silently green.
fn findFixture(
    a: Allocator,
    io: Io,
    out: *Io.Writer,
    root: []const u8,
    name: []const u8,
) !?Fixture {
    const candidates = [_]struct { file: []const u8, kind: ?FixtureKind }{
        .{ .file = "song.mid", .kind = .smf },
        .{ .file = "song.it", .kind = .it },
        .{ .file = "doc.sjon", .kind = null },
    };
    for (candidates) |c| {
        const path = try std.fs.path.join(a, &.{ root, name, c.file });
        const bytes = Io.Dir.cwd().readFileAllocOptions(io, path, a, .limited(MAX_FILE_BYTES), .of(u8), 0) catch continue;
        const kind = c.kind orelse {
            try out.print("corpus: {s}: UNRUN doc.sjon — timeline documents land with P107's documents half\n", .{name});
            return null;
        };
        return .{ .file = c.file, .bytes = bytes, .kind = kind };
    }
    try out.print("corpus: {s}: no fixture (expected song.mid, song.it or doc.sjon)\n", .{name});
    return null;
}

// ---------------------------------------------------------------------------
// The harness — an ordered script of directives
// ---------------------------------------------------------------------------

/// One directive, executed in document order against the case's fixture.
const Directive = union(enum) {
    /// What the core made of the bytes, and everything it complained of.
    read,
    /// Rungs 1 and 2 of plan 09's ladder.
    roundtrip,
    /// The IT timing walk's `RowMap`, bounded by `max_rows`.
    walk: u32,
    /// The canonical writer's own output, with its switches.
    write: struct { format0: bool },
    /// A head the manifest declares and this half does not implement.
    /// It carries the head so the report can name it.
    unrun: []const u8,
};

/// Read `times.sjon`. Null = the case is void (already reported).
///
/// SHAPE is the schema's: the source is validated against the preloaded
/// harness vocabulary, so an unknown head, a `:max-rows` past the walk's
/// ceiling or a `:format0` that is not a boolean is an SJON diagnostic
/// with a SPAN before a single field is read. What stays here is what a
/// form-at-a-time schema cannot see: document ORDER, "at least one
/// directive", and which heads this half implements at all.
fn parseHarness(
    a: Allocator,
    gpa: Allocator,
    harness_schema: *const Schema,
    out: *Io.Writer,
    name: []const u8,
    src: [:0]const u8,
) !?[]const Directive {
    // Validation never aborts on malformed input (collection over
    // abort) — parse errors arrive as diagnostics alongside schema ones.
    var v = Schema.validate(gpa, harness_schema, src) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
    };
    defer v.deinit();
    if (v.hasErrors()) {
        try out.print("corpus: {s}: times.sjon does not validate:\n", .{name});
        for (v.diagnostics) |d| {
            if (d.severity != .err) continue;
            try out.print("  {s}: {d}..{d}: {s}\n", .{ @tagName(d.code), d.span.start, d.span.end, d.message });
        }
        return null;
    }
    const tree = &v.tree;
    const view: sjon.EffectiveView.EffectiveView = .init(&v.tree, &v.materialized_defaults);

    var directives: std.ArrayList(Directive) = .empty;
    for (tree.root) |idx| {
        if (tree.tagOf(idx) != .form) {
            // A bare value at the root is not a form, so no `(form …)`
            // declaration governs it and the validator has nothing to
            // say about it.
            try out.print("corpus: {s}: times.sjon: only directive forms are allowed at the root\n", .{name});
            return null;
        }
        const hdr = tree.formHeader(idx);
        if (std.mem.eql(u8, hdr.head, "read")) {
            try directives.append(a, .read);
        } else if (std.mem.eql(u8, hdr.head, "roundtrip")) {
            try directives.append(a, .roundtrip);
        } else if (std.mem.eql(u8, hdr.head, "walk")) {
            try directives.append(a, .{ .walk = @intCast(effInt(&view, tree, idx, "max-rows")) });
        } else if (std.mem.eql(u8, hdr.head, "write")) {
            try directives.append(a, .{ .write = .{ .format0 = effBool(&view, tree, idx, "format0") } });
        } else {
            // `unknown_form` is an error and an erroring document never
            // reaches here, so the head is one the manifest declares —
            // and one P107's documents half implements.
            try directives.append(a, .{ .unrun = try a.dupe(u8, hdr.head) });
        }
    }

    if (directives.items.len == 0) {
        try out.print("corpus: {s}: times.sjon: no directives (a case has to ask something)\n", .{name});
        return null;
    }
    return directives.items;
}

/// The effective `:key` on `form` as a non-negative integer — the
/// author's literal when written, else the manifest's `:default` (a
/// default has ONE spelling, and it is the schema's). Every key read
/// this way is declared `:integer true` with bounds, so the conversion
/// below is exhaustive by validation rather than by hope.
fn effInt(
    view: *const sjon.EffectiveView.EffectiveView,
    tree: *const Ast.Tree,
    form: NodeIndex,
    key: []const u8,
) u64 {
    const ev = view.getEffectiveValue(form, key).?;
    const n: f64 = switch (ev) {
        .author => |node| switch (tree.tagOf(node)) {
            .number => tree.numberOf(node),
            .number_i64 => @floatFromInt(tree.numberI64Of(node)),
            .number_u64 => @floatFromInt(tree.numberU64Of(node)),
            else => unreachable,
        },
        .default => |entry| switch (entry.value) {
            .number => |x| x,
            .integer_i64 => |x| @floatFromInt(x),
            .integer_u64 => |x| @floatFromInt(x),
            else => unreachable,
        },
    };
    std.debug.assert(n >= 0 and n == @floor(n));
    return @intFromFloat(n);
}

/// The effective `:key` on `form` as a boolean, the same way.
fn effBool(
    view: *const sjon.EffectiveView.EffectiveView,
    tree: *const Ast.Tree,
    form: NodeIndex,
    key: []const u8,
) bool {
    const ev = view.getEffectiveValue(form, key).?;
    return switch (ev) {
        .author => |node| tree.tagOf(node) == .boolean_true,
        .default => |entry| switch (entry.value) {
            .boolean => |b| b,
            else => unreachable,
        },
    };
}

// ---------------------------------------------------------------------------
// Canonical rendering — the byte-pinned format
// ---------------------------------------------------------------------------

/// Where a defect that VOIDS a golden is reported: the case's name and
/// the run's report writer. `out` is null in tests, which have no report
/// to write and assert on the return value instead.
const Report = struct {
    out: ?*Io.Writer,
    name: []const u8,

    fn say(self: Report, comptime fmt: []const u8, args: anytype) void {
        const out = self.out orelse return;
        out.print("corpus: {s}: " ++ fmt, .{self.name} ++ args) catch {};
    }
};

/// `Io.Writer.Allocating` fails one way only, and a golden half-written
/// is a golden not written: every print goes through here so the error
/// set stays `Error`.
fn p(w: *Io.Writer, comptime fmt: []const u8, args: anytype) Error!void {
    w.print(fmt, args) catch return error.OutOfMemory;
}

fn pw(w: *Io.Writer, bytes: []const u8) Error!void {
    w.writeAll(bytes) catch return error.OutOfMemory;
}

/// The SHA-256 of `bytes` as 64 lowercase hex digits. What the goldens
/// pin a byte string by — the fixture, the rewrite, the merged file —
/// and what x86_64, aarch64 and wasm32 must agree on.
fn writeDigest(w: *Io.Writer, bytes: []const u8) Error!void {
    var digest: [Sha256.digest_length]u8 = undefined;
    Sha256.hash(bytes, &digest, .{});
    for (digest) |b| try p(w, "{x:0>2}", .{b});
}

/// The severity a golden spells. `Diag.Severity.err` is `error` in text:
/// the enum's name is a Zig keyword and the golden is not Zig.
fn severityName(s: Diag.Severity) []const u8 {
    return switch (s) {
        .err => "error",
        .warning => "warning",
        .info => "info",
    };
}

/// One `(diag …)` child per entry, each on its own line at `indent`.
/// Nothing at all when the list is empty, so a clean read is one line.
///
/// False = a message carries a control byte and the golden is void
/// (a diagnostic can quote a file's own bytes — a chunk tag, a name —
/// and an unprintable byte in a golden is not reviewable text).
fn renderDiags(
    w: *Io.Writer,
    indent: []const u8,
    diags: *const Diag.List,
    rep: Report,
) Error!bool {
    for (diags.items()) |d| {
        try p(w, "\n{s}(diag :code {d} :severity {s} :start {d} :end {d} :message \"", .{
            indent,
            @intFromEnum(d.code),
            severityName(d.severity),
            d.span.start,
            d.span.end,
        });
        for (d.message) |b| {
            if (b < 0x20) {
                rep.say("control byte in a diagnostic message — not renderable\n", .{});
                return false;
            }
            if (b == '"' or b == '\\') try p(w, "\\", .{});
            try p(w, "{c}", .{b});
        }
        try pw(w, "\")");
    }
    return true;
}

/// A file's own text — a module title, a chunk tag — inside a golden's
/// string. Same escaping and the same control-byte refusal.
fn renderText(w: *Io.Writer, text: []const u8, rep: Report) Error!bool {
    for (text) |b| {
        if (b < 0x20) {
            rep.say("control byte in a name — not renderable\n", .{});
            return false;
        }
        if (b == '"' or b == '\\') try p(w, "\\", .{});
        try p(w, "{c}", .{b});
    }
    return true;
}

/// Render one case's whole golden. False = a defect that voids it
/// (already reported): a directive the fixture cannot answer, a
/// directive this half does not implement, an unrenderable byte.
fn renderCase(
    gpa: Allocator,
    a: Allocator,
    w: *Io.Writer,
    fixture: Fixture,
    directives: []const Directive,
    rep: Report,
) Error!bool {
    try pw(w, GENERATED_HEADER);
    // The fixture is pinned by length and hash before anything is asked
    // of it: `zig build fixtures` regenerating different bytes moves
    // every golden that describes them, which is the drift showing.
    try p(w, "(fixture :file \"{s}\" :bytes {d} :sha256 \"", .{ fixture.file, fixture.bytes.len });
    try writeDigest(w, fixture.bytes);
    try pw(w, "\")\n");

    return switch (fixture.kind) {
        .smf => try renderSmfCase(gpa, a, w, fixture, directives, rep),
        .it => try renderItCase(gpa, a, w, fixture, directives, rep),
    };
}

// ---- the SMF half ----

fn renderSmfCase(
    gpa: Allocator,
    a: Allocator,
    w: *Io.Writer,
    fixture: Fixture,
    directives: []const Directive,
    rep: Report,
) Error!bool {
    // Read ONCE for the whole case: every directive asks about the same
    // bytes, and reading them twice would be two answers to gate.
    var r = try smf.read(gpa, fixture.bytes);
    defer r.deinit();

    for (directives) |d| switch (d) {
        .read => {
            try pw(w, "(read\n  ");
            const seq = &r.sequence;
            try p(w, "(smf :format {d} :division {d} :smpte ", .{
                seq.format,
                seq.division.pulsesPerQuarter(),
            });
            switch (seq.division) {
                // `:division` is always the GRID the file's ticks are
                // on; `:smpte` is what the header actually spelled, so
                // a SMPTE case pins both the file and the conversion.
                .ppq => try pw(w, "none"),
                .smpte => |s| try p(w, "[{d} {d}]", .{ s.fps, s.tpf }),
            }
            // How many events were read ON running status — the one
            // fact about a `.mid`'s LAYOUT that survives into the value,
            // and what `smf-running-status` is a case about.
            var on_running: usize = 0;
            for (r.source_map.tracks) |tm| {
                for (tm.events) |site| {
                    if (site.running_status) on_running += 1;
                }
            }
            try p(w, " :tracks {d} :events {d} :running-status {d} :foreign {d})", .{
                seq.tracks.len,
                seq.eventCount(),
                on_running,
                seq.foreign.len,
            });
            if (!try renderDiags(w, "  ", &r.diags, rep)) return false;
            try pw(w, ")\n");
        },
        .roundtrip => {
            // Rung 1: the canonical writer's output against the very
            // bytes it is supposed to reproduce.
            var rewrite = try smf.write(gpa, &r.sequence, .{});
            defer rewrite.deinit();
            try p(w, "(roundtrip\n  (rung1 :ok {} :sha256 \"", .{
                std.mem.eql(u8, rewrite.bytes, fixture.bytes),
            });
            try writeDigest(w, rewrite.bytes);
            try pw(w, "\"");
            if (!try renderDiags(w, "    ", &rewrite.diags, rep)) return false;
            try pw(w, ")\n");

            // Rung 2: the same events came back, whatever the layout.
            var again = try smf.read(gpa, rewrite.bytes);
            defer again.deinit();
            const differs = try smfDifference(a, &r.sequence, &again.sequence);
            try p(w, "  (rung2 :ok {}", .{differs == null});
            if (differs) |why| {
                try pw(w, " :differs \"");
                if (!try renderText(w, why, rep)) return false;
                try pw(w, "\"");
            }
            if (!try renderDiags(w, "    ", &again.diags, rep)) return false;
            try pw(w, "))\n");
        },
        .write => |opts| {
            var written = try smf.write(gpa, &r.sequence, .{ .format0 = opts.format0 });
            defer written.deinit();
            // Read the output back for the counts: a file nobody can
            // read is not a file, and the merge's event count is the
            // point of the directive.
            var back = try smf.read(gpa, written.bytes);
            defer back.deinit();
            try p(w, "(write :format0 {} :sha256 \"", .{opts.format0});
            try writeDigest(w, written.bytes);
            try p(w, "\" :bytes {d} :tracks {d} :events {d}", .{
                written.bytes.len,
                back.sequence.tracks.len,
                back.sequence.eventCount(),
            });
            if (!try renderDiags(w, "  ", &written.diags, rep)) return false;
            try pw(w, ")\n");
        },
        .walk => {
            rep.say("(walk …) needs an .it fixture; this case's is {s}\n", .{fixture.file});
            return false;
        },
        .unrun => |head| {
            rep.say("UNRUN {s} — the directive lands with P107's documents half\n", .{head});
            return false;
        },
    };
    return true;
}

/// Null when two sequences hold the same events — rung 2's question.
/// Otherwise the first difference, named well enough to find it: the
/// golden carries the sentence, so a regression is a diff and not a
/// bisect.
///
/// Every event's `at`, kind and ACTIVE payload (an extern union's
/// inactive bytes are indeterminate — `eqlOutsidePool` is the one
/// comparison allowed), the pool bytes each payload names, and the
/// foreign chunks the reader preserved.
fn smfDifference(
    a: Allocator,
    x: *const smf.Sequence,
    y: *const smf.Sequence,
) Error!?[]const u8 {
    if (x.format != y.format) return try std.fmt.allocPrint(a, "format {d} became {d}", .{ x.format, y.format });
    if (x.division.pulsesPerQuarter() != y.division.pulsesPerQuarter()) return try std.fmt.allocPrint(
        a,
        "the grid {d} became {d}",
        .{ x.division.pulsesPerQuarter(), y.division.pulsesPerQuarter() },
    );
    if (x.tracks.len != y.tracks.len) return try std.fmt.allocPrint(a, "{d} tracks became {d}", .{ x.tracks.len, y.tracks.len });

    for (x.tracks, y.tracks, 0..) |tx, ty, ti| {
        if (tx.events.len != ty.events.len) return try std.fmt.allocPrint(
            a,
            "track {d}: {d} events became {d}",
            .{ ti, tx.events.len, ty.events.len },
        );
        for (tx.events, ty.events, 0..) |ex, ey, ei| {
            if (ex.at != ey.at) return try std.fmt.allocPrint(a, "track {d} event {d}: tick {d} became {d}", .{ ti, ei, ex.at, ey.at });
            if (ex.kind != ey.kind) return try std.fmt.allocPrint(a, "track {d} event {d}: {s} became {s}", .{ ti, ei, @tagName(ex.kind), @tagName(ey.kind) });
            if (!ex.payload.eqlOutsidePool(ey.payload, ex.kind)) return try std.fmt.allocPrint(
                a,
                "track {d} event {d}: the {s} payload changed",
                .{ ti, ei, @tagName(ex.kind) },
            );
            const bx = ex.payload.poolBytes(ex.kind);
            const by = ey.payload.poolBytes(ey.kind);
            if (bx != null and !std.mem.eql(u8, x.bytesOf(bx.?), y.bytesOf(by.?))) return try std.fmt.allocPrint(
                a,
                "track {d} event {d}: the {s} bytes changed",
                .{ ti, ei, @tagName(ex.kind) },
            );
        }
    }

    if (x.foreign.len != y.foreign.len) return try std.fmt.allocPrint(a, "{d} foreign chunks became {d}", .{ x.foreign.len, y.foreign.len });
    for (x.foreign, y.foreign, 0..) |fx, fy, i| {
        if (!std.mem.eql(u8, &fx.tag, &fy.tag)) return try std.fmt.allocPrint(a, "foreign chunk {d} changed tag", .{i});
        if (!std.mem.eql(u8, x.bytesOf(fx.bytes), y.bytesOf(fy.bytes))) return try std.fmt.allocPrint(a, "foreign chunk {d} changed bytes", .{i});
    }
    return null;
}

// ---- the IT half ----

fn renderItCase(
    gpa: Allocator,
    a: Allocator,
    w: *Io.Writer,
    fixture: Fixture,
    directives: []const Directive,
    rep: Report,
) Error!bool {
    // The module's opaque regions point INTO these bytes: a `Module` is
    // meaningful only against the file it was read from, which is why
    // the anchor is handed to every writer below.
    var r = try itf.read.read(gpa, fixture.bytes);
    defer r.deinit();

    for (directives) |d| switch (d) {
        .read => {
            const m = &r.module;
            try pw(w, "(read\n  (it :title \"");
            if (!try renderText(w, itf.model.nameText(&m.header.title), rep)) return false;
            try p(w, "\" :speed {d} :tempo {d} :orders {d} :patterns {d} :instruments {d} :samples {d} :message-len {d} :tmpu {})", .{
                m.header.initial_speed,
                m.header.initial_tempo,
                m.orders.len,
                m.patterns.len,
                m.instruments.len,
                m.samples.len,
                m.message.len,
                m.tmpu != null,
            });
            if (!try renderDiags(w, "  ", &r.diags, rep)) return false;
            try pw(w, ")\n");
        },
        .roundtrip => {
            var rewrite = try itf.write.write(gpa, &r.module, fixture.bytes, .{});
            defer rewrite.deinit();
            try p(w, "(roundtrip\n  (rung1 :ok {} :sha256 \"", .{
                std.mem.eql(u8, rewrite.bytes, fixture.bytes),
            });
            try writeDigest(w, rewrite.bytes);
            try pw(w, "\"");
            if (!try renderDiags(w, "    ", &rewrite.diags, rep)) return false;
            try pw(w, ")\n");

            var again = try itf.read.read(gpa, rewrite.bytes);
            defer again.deinit();
            const differs = try itDifference(a, &r.module, fixture.bytes, &again.module, rewrite.bytes);
            try p(w, "  (rung2 :ok {}", .{differs == null});
            if (differs) |why| {
                try pw(w, " :differs \"");
                if (!try renderText(w, why, rep)) return false;
                try pw(w, "\"");
            }
            if (!try renderDiags(w, "    ", &again.diags, rep)) return false;
            try pw(w, "))\n");
        },
        .walk => |max_rows| {
            if (!try renderWalk(gpa, w, &r.module, max_rows, rep)) return false;
        },
        .write => |opts| {
            if (opts.format0) {
                // `:format0` is the SMF merge; an IT module has no
                // tracks to merge and the schema says so in the key's
                // own description.
                rep.say("(write :format0 true) is the SMF merge; this case's fixture is {s}\n", .{fixture.file});
                return false;
            }
            var written = try itf.write.write(gpa, &r.module, fixture.bytes, .{});
            defer written.deinit();
            var back = try itf.read.read(gpa, written.bytes);
            defer back.deinit();
            try pw(w, "(write :sha256 \"");
            try writeDigest(w, written.bytes);
            try p(w, "\" :bytes {d} :orders {d} :patterns {d} :samples {d}", .{
                written.bytes.len,
                back.module.orders.len,
                back.module.patterns.len,
                back.module.samples.len,
            });
            if (!try renderDiags(w, "  ", &written.diags, rep)) return false;
            try pw(w, ")\n");
        },
        .unrun => |head| {
            rep.say("UNRUN {s} — the directive lands with P107's documents half\n", .{head});
            return false;
        },
    };
    return true;
}

/// The IT timing walk's `RowMap`, as text: every row PLAYED with its
/// start and length, the tempo segments, the note onsets, the total and
/// the loop point, then whatever the walk complained of.
///
/// Rows and onsets are capped: a runaway module plays a million rows,
/// and a golden nobody can read is not evidence. What was left out is
/// stated rather than dropped.
fn renderWalk(
    gpa: Allocator,
    w: *Io.Writer,
    module: *const itf.Module,
    max_rows: u32,
    rep: Report,
) Error!bool {
    var map = try itf.walk.derive(gpa, module, .{ .max_rows = max_rows });
    defer map.deinit();

    try p(w, "(walk :max-rows {d}", .{max_rows});
    for (map.rows[0..@min(map.rows.len, MAX_ROWS_ECHOED)]) |row| {
        try p(w, "\n  (row :order {d} :pattern {d} :row {d} :start {d} :ticks {d})", .{
            row.order, row.pattern, row.row, row.start_tick, row.ticks,
        });
    }
    if (map.rows.len > MAX_ROWS_ECHOED) try p(w, "\n  (rows-elided {d})", .{map.rows.len - MAX_ROWS_ECHOED});

    for (map.segments) |seg| {
        try p(w, "\n  (segment :tick {d} :tempo {d})", .{ seg.start_tick, seg.tempo });
    }
    for (map.onsets[0..@min(map.onsets.len, MAX_ONSETS_ECHOED)]) |onset| {
        try p(w, "\n  (onset :ch {d} :tick {d} :note {d})", .{ onset.channel, onset.tick, onset.cell.note });
    }
    if (map.onsets.len > MAX_ONSETS_ECHOED) try p(w, "\n  (onsets-elided {d})", .{map.onsets.len - MAX_ONSETS_ECHOED});

    try p(w, "\n  (total :ticks {d} :loop-row ", .{map.total_ticks});
    if (map.loop_row) |loop| {
        try p(w, "{d})", .{loop});
    } else {
        // No loop point: the walk stopped for another reason — the
        // runaway cap, or a module with nothing to play.
        try pw(w, "none)");
    }
    if (!try renderDiags(w, "  ", &map.diags, rep)) return false;
    try pw(w, ")\n");
    return true;
}

/// Null when two modules hold the same music — rung 2's question for
/// `.it`. Header fields, orders, patterns cell by cell, the message, and
/// every pass-through region compared as BYTES against its own anchor.
///
/// The edit-history block is deliberately not compared: the writer drops
/// it unless `preserve_history` asks for it (it 03), so its absence is
/// policy rather than loss.
fn itDifference(
    a: Allocator,
    x: *const itf.Module,
    x_src: []const u8,
    y: *const itf.Module,
    y_src: []const u8,
) Error!?[]const u8 {
    const hx = &x.header;
    const hy = &y.header;
    if (!std.mem.eql(u8, &hx.title, &hy.title)) return try std.fmt.allocPrint(a, "the title changed", .{});
    const fields = [_]struct { name: []const u8, x: u32, y: u32 }{
        .{ .name = "highlight-minor", .x = hx.highlight_minor, .y = hy.highlight_minor },
        .{ .name = "highlight-major", .x = hx.highlight_major, .y = hy.highlight_major },
        .{ .name = "cwtv", .x = hx.cwtv, .y = hy.cwtv },
        .{ .name = "cmwt", .x = hx.cmwt, .y = hy.cmwt },
        .{ .name = "flags", .x = hx.flags, .y = hy.flags },
        .{ .name = "special", .x = hx.special, .y = hy.special },
        .{ .name = "global-volume", .x = hx.global_volume, .y = hy.global_volume },
        .{ .name = "mix-volume", .x = hx.mix_volume, .y = hy.mix_volume },
        .{ .name = "initial-speed", .x = hx.initial_speed, .y = hy.initial_speed },
        .{ .name = "initial-tempo", .x = hx.initial_tempo, .y = hy.initial_tempo },
        .{ .name = "pan-separation", .x = hx.pan_separation, .y = hy.pan_separation },
        .{ .name = "pitch-wheel-depth", .x = hx.pitch_wheel_depth, .y = hy.pitch_wheel_depth },
    };
    for (fields) |f| {
        if (f.x != f.y) return try std.fmt.allocPrint(a, "{s} {d} became {d}", .{ f.name, f.x, f.y });
    }
    if (!std.mem.eql(u8, &hx.channel_pan, &hy.channel_pan)) return try std.fmt.allocPrint(a, "the channel pan table changed", .{});
    if (!std.mem.eql(u8, &hx.channel_vol, &hy.channel_vol)) return try std.fmt.allocPrint(a, "the channel volume table changed", .{});

    if (!std.mem.eql(u8, x.orders, y.orders)) return try std.fmt.allocPrint(
        a,
        "the order list changed ({d} entries against {d})",
        .{ x.orders.len, y.orders.len },
    );
    if (!std.mem.eql(u8, x.message, y.message)) return try std.fmt.allocPrint(a, "the song message changed", .{});

    if (x.patterns.len != y.patterns.len) return try std.fmt.allocPrint(a, "{d} patterns became {d}", .{ x.patterns.len, y.patterns.len });
    for (x.patterns, y.patterns, 0..) |px, py, i| {
        if (px.rows != py.rows) return try std.fmt.allocPrint(a, "pattern {d}: {d} rows became {d}", .{ i, px.rows, py.rows });
        for (px.cells, py.cells, 0..) |cx, cy, at| {
            if (std.meta.eql(cx, cy)) continue;
            return try std.fmt.allocPrint(a, "pattern {d} row {d} channel {d} changed", .{
                i,
                at / itf.model.channels,
                at % itf.model.channels,
            });
        }
    }

    if (x.instruments.len != y.instruments.len) return try std.fmt.allocPrint(a, "{d} instruments became {d}", .{ x.instruments.len, y.instruments.len });
    for (x.instruments, y.instruments, 0..) |ix, iy, i| {
        if (!std.mem.eql(u8, &ix.name, &iy.name)) return try std.fmt.allocPrint(a, "instrument {d} changed name", .{i});
        if (try regionDiffers(a, "instrument", i, ix.raw, x_src, iy.raw, y_src)) |why| return why;
    }

    if (x.samples.len != y.samples.len) return try std.fmt.allocPrint(a, "{d} samples became {d}", .{ x.samples.len, y.samples.len });
    for (x.samples, y.samples, 0..) |sx, sy, i| {
        if (!std.mem.eql(u8, &sx.name, &sy.name)) return try std.fmt.allocPrint(a, "sample {d} changed name", .{i});
        if (sx.bits != sy.bits or sx.channels != sy.channels or sx.enc != sy.enc) return try std.fmt.allocPrint(
            a,
            "sample {d}'s descriptor changed ({d}-bit {s} became {d}-bit {s})",
            .{ i, sx.bits, @tagName(sx.enc), sy.bits, @tagName(sy.enc) },
        );
        if (try regionDiffers(a, "sample header", i, sx.raw, x_src, sy.raw, y_src)) |why| return why;
        if (try regionDiffers(a, "sample data", i, sx.data, x_src, sy.data, y_src)) |why| return why;
    }

    if (x.foreign.len != y.foreign.len) return try std.fmt.allocPrint(a, "{d} foreign chunks became {d}", .{ x.foreign.len, y.foreign.len });
    for (x.foreign, y.foreign, 0..) |fx, fy, i| {
        if (!std.mem.eql(u8, &fx.tag, &fy.tag)) return try std.fmt.allocPrint(a, "foreign chunk {d} changed tag", .{i});
        if (try regionDiffers(a, "foreign chunk", i, fx.raw, x_src, fy.raw, y_src)) |why| return why;
    }

    if ((x.midi_config == null) != (y.midi_config == null)) return try std.fmt.allocPrint(a, "the MIDI configuration appeared or vanished", .{});
    if (x.midi_config != null) {
        if (try regionDiffers(a, "MIDI configuration", 0, x.midi_config.?, x_src, y.midi_config.?, y_src)) |why| return why;
    }
    if ((x.tmpu == null) != (y.tmpu == null)) return try std.fmt.allocPrint(a, "the TMPU chunk appeared or vanished", .{});
    if (x.tmpu != null) {
        if (try regionDiffers(a, "TMPU payload", 0, x.tmpu.?, x_src, y.tmpu.?, y_src)) |why| return why;
    }
    return null;
}

/// Two opaque regions, each read against its OWN anchor: pass-through
/// means the bytes come back, not that the offsets do.
fn regionDiffers(
    a: Allocator,
    comptime what: []const u8,
    index: usize,
    rx: itf.Region,
    x_src: []const u8,
    ry: itf.Region,
    y_src: []const u8,
) Error!?[]const u8 {
    const bx = rx.slice(x_src);
    const by = ry.slice(y_src);
    if (bx == null or by == null) return try std.fmt.allocPrint(
        a,
        what ++ " {d} left its anchor's bytes",
        .{index},
    );
    if (!std.mem.eql(u8, bx.?, by.?)) return try std.fmt.allocPrint(
        a,
        what ++ " {d} changed bytes ({d} against {d})",
        .{ index, bx.?.len, by.?.len },
    );
    return null;
}

// ---------------------------------------------------------------------------
// Reporting
// ---------------------------------------------------------------------------

/// The first line at which two goldens part, expected against actual.
const Mismatch = struct {
    line: usize,
    expected: ?[]const u8,
    actual: ?[]const u8,
};

/// Null when the two texts are byte-equal. Otherwise the first line that
/// differs, with `null` on the side that ended first — enough to see a
/// changed hash or a missing row without dumping whole files.
fn firstDifference(expected: []const u8, actual: []const u8) ?Mismatch {
    if (std.mem.eql(u8, expected, actual)) return null;
    var exp_lines = std.mem.splitScalar(u8, expected, '\n');
    var act_lines = std.mem.splitScalar(u8, actual, '\n');
    var line: usize = 1;
    while (true) : (line += 1) {
        const e = exp_lines.next();
        const ac = act_lines.next();
        if (e == null and ac == null) {
            // Line-identical but not byte-identical: the difference is
            // in the line terminators themselves.
            return .{ .line = 0, .expected = null, .actual = null };
        }
        if (e != null and ac != null and std.mem.eql(u8, e.?, ac.?)) continue;
        return .{ .line = line, .expected = e, .actual = ac };
    }
}

fn reportMismatch(out: *Io.Writer, name: []const u8, diff: Mismatch) !void {
    if (diff.line == 0) {
        try out.print("corpus: {s}: MISMATCH (line-identical; byte difference)\n", .{name});
        return;
    }
    try out.print("corpus: {s}: MISMATCH at line {d}\n  expected: {s}\n  actual:   {s}\n", .{
        name,
        diff.line,
        diff.expected orelse "<end of file>",
        diff.actual orelse "<end of file>",
    });
    try out.print("corpus: {s}: `zig build corpus -- --update` regenerates (review the diff)\n", .{name});
}

// ---------------------------------------------------------------------------
// Tests — the harness vocabulary, the renderer and the verdict.
// Discovered through `root.zig`'s test block.
// ---------------------------------------------------------------------------

const t_ = std.testing;

/// One harness source through the real reader, with the report captured.
/// `.directives` is null exactly when the runner would fail the case;
/// `.report` is what it printed — which is how the tests below pin WHICH
/// layer refused, the schema or the runner.
const ParseProbe = struct { directives: ?[]const Directive, report: []const u8 };

fn testParse(a: Allocator, src: [:0]const u8) !ParseProbe {
    var hs = try Schema.loadCorpus(t_.allocator);
    defer hs.deinit();
    var sink: Io.Writer.Allocating = .init(a);
    const d = try parseHarness(a, t_.allocator, &hs, &sink.writer, "test", src);
    return .{ .directives = d, .report = sink.written() };
}

/// The first line of a schema report — `parseHarness` prints it before
/// the per-diagnostic lines and nothing else does.
const SCHEMA_REFUSED = "does not validate";

test "corpus harness: the embedded manifest preloads clean and declares every directive" {
    var hs = try Schema.loadCorpus(t_.allocator);
    defer hs.deinit();

    try t_.expectEqual(@as(usize, 0), hs.preloaded.diagnostics.len);
    try t_.expectEqual(@as(usize, 1), hs.preloaded.plugins.len);
    try t_.expectEqualStrings("tempura-corpus", hs.preloaded.plugins[0].name);
    for ([_][]const u8{
        "read", "roundtrip", "walk",   "write", "at",
        "snap", "plan",      "timing", "build", "export-score",
        "dump",
    }) |head| {
        try t_.expect(hs.preloaded.schema.lookupForm(head, null) == .found);
    }
}

test "corpus harness: a well-formed file reads through the schema, defaults and all" {
    var arena = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    const d = (try testParse(a,
        \\(read)
        \\(roundtrip)
        \\(walk)
        \\(walk :max-rows 3)
        \\(write)
        \\(write :format0 true)
    )).directives.?;

    try t_.expectEqual(@as(usize, 6), d.len);
    try t_.expectEqual(Directive.read, d[0]);
    try t_.expectEqual(Directive.roundtrip, d[1]);
    // `:max-rows` omitted is the MANIFEST's default, read back through
    // `EffectiveView` — one spelling per default, and it is the walk's
    // own ceiling.
    try t_.expectEqual(@as(u32, 1 << 20), d[2].walk);
    try t_.expectEqual(@as(u32, 3), d[3].walk);
    try t_.expectEqual(false, d[4].write.format0);
    try t_.expectEqual(true, d[5].write.format0);
}

test "corpus harness: the schema refuses what the runner would otherwise hand-check" {
    var arena = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    // Each of these is an SJON diagnostic carrying a span, pinned by
    // CODE — so a runner check quietly taking the refusal back would
    // fail here.
    const cases = [_]struct { src: [:0]const u8, code: []const u8 }{
        .{ .src = "(walk :max-rows 0)", .code = "number_below_min" },
        .{ .src = "(walk :max-rows 1048577)", .code = "number_above_max" },
        .{ .src = "(walk :max-rows 1.5)", .code = "number_not_integer" },
        .{ .src = "(walk :max-rows 3b)", .code = "unit_forbidden" },
        .{ .src = "(write :format0 1)", .code = "wrong_underlying" },
        .{ .src = "(read :bogus 1)", .code = "unknown_key" },
        .{ .src = "(rewind :to 0)", .code = "unknown_form" },
    };
    for (cases) |c| {
        const probe = try testParse(a, c.src);
        try t_.expect(probe.directives == null);
        try t_.expect(std.mem.indexOf(u8, probe.report, SCHEMA_REFUSED) != null);
        try t_.expect(std.mem.indexOf(u8, probe.report, c.code) != null);
    }
}

test "corpus harness: what a schema cannot see stays the runner's" {
    var arena = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    // A bare value at the root is governed by no `(form …)` declaration,
    // and "at least one directive" is a document-level fact. Neither is
    // a shape a form-at-a-time schema sees, so both refusals are the
    // runner's — and must NOT come from a diagnostic.
    const srcs = [_][:0]const u8{
        "(read)\nsong.mid",
        "; a harness that asks nothing at all\n",
    };
    for (srcs) |src| {
        const probe = try testParse(a, src);
        try t_.expect(probe.directives == null);
        try t_.expect(std.mem.indexOf(u8, probe.report, SCHEMA_REFUSED) == null);
    }
}

test "corpus harness: a directive this half does not implement is UNRUN, never a pass" {
    var arena = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    // The documents half's verbs validate — they are the same
    // vocabulary — and come back as `unrun`, which fails the case.
    const d = (try testParse(a,
        \\(read)
        \\(dump)
        \\(timing)
    )).directives.?;
    try t_.expectEqual(@as(usize, 3), d.len);
    try t_.expectEqual(Directive.read, d[0]);
    try t_.expectEqualStrings("dump", d[1].unrun);
    try t_.expectEqualStrings("timing", d[2].unrun);
}

test "corpus verdict: byte-equal is silence, and a difference names the first line" {
    try t_.expectEqual(@as(?Mismatch, null), firstDifference("(a)\n(b)\n", "(a)\n(b)\n"));

    const diff = firstDifference("(a)\n(b)\n", "(a)\n(c)\n").?;
    try t_.expectEqual(@as(usize, 2), diff.line);
    try t_.expectEqualStrings("(b)", diff.expected.?);
    try t_.expectEqualStrings("(c)", diff.actual.?);

    // A golden that ends early, and one that runs on: the side that ran
    // out is `null`, which the report spells `<end of file>`.
    const short = firstDifference("(a)\n", "(a)\n(b)\n").?;
    try t_.expectEqual(@as(usize, 2), short.line);
    try t_.expectEqualStrings("", short.expected.?);
    try t_.expectEqualStrings("(b)", short.actual.?);

    // Line 0 is the report's "line-identical, byte difference" arm: it
    // cannot be reached by a line difference, only by a terminator one.
    const trailing = firstDifference("(a)", "(a)\n");
    try t_.expect(trailing != null);
}

/// A case rendered the way `runCase` renders it, into the test's arena.
/// The report writer is a sink: these cases have no defect to report.
fn testRender(a: Allocator, fixture: Fixture, directives: []const Directive) ![]const u8 {
    var report: Io.Writer.Allocating = .init(a);
    var aw: Io.Writer.Allocating = .init(a);
    const rep: Report = .{ .out = &report.writer, .name = "test" };
    try t_.expect(try renderCase(t_.allocator, a, &aw.writer, fixture, directives, rep));
    try t_.expectEqualStrings("", report.written());
    return aw.written();
}

/// The lowercase hex digest, as the golden spells it — the test's own
/// hand on the same bytes, so an expectation below says WHICH buffer the
/// renderer was supposed to hash.
fn testDigest(a: Allocator, bytes: []const u8) ![]const u8 {
    var out: Io.Writer.Allocating = .init(a);
    try writeDigest(&out.writer, bytes);
    return out.written();
}

test "corpus render: an SMF case — the fixture line, the read echo, both rungs and the writer" {
    var arena = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const gpa = t_.allocator;

    // One canonical file: the writer's own output, so rung 1 holds.
    var b: smf.Builder = .init(gpa);
    errdefer b.deinit();
    b.format = 0;
    b.division = .{ .ppq = 96 };
    const track = try b.addTrack();
    try b.addEvent(track, 0, .set_tempo, .{ .tempo = 500_000 });
    try b.addEvent(track, 0, .note_on, .{ .note = .{ .ch = 0, .key = 60, .vel = 100 } });
    try b.addEvent(track, 96, .note_off, .{ .note = .{ .ch = 0, .key = 60, .vel = 64 } });
    var seq = try b.finish();
    defer seq.deinit();
    var file = try smf.write(gpa, &seq, .{});
    defer file.deinit();

    // …and the same bytes through the format-0 merge, which is what the
    // `(write …)` line has to be describing.
    var back = try smf.read(gpa, file.bytes);
    defer back.deinit();
    var merged = try smf.write(gpa, &back.sequence, .{ .format0 = true });
    defer merged.deinit();

    const text = try testRender(a, .{ .file = "song.mid", .bytes = file.bytes, .kind = .smf }, &.{
        .read,
        .roundtrip,
        .{ .write = .{ .format0 = true } },
    });

    const want = try std.fmt.allocPrint(a,
        \\; tempura corpus golden — GENERATED by `zig build corpus -- --update`; do not hand-edit.
        \\(fixture :file "song.mid" :bytes {d} :sha256 "{s}")
        \\(read
        \\  (smf :format 0 :division 96 :smpte none :tracks 1 :events 4 :running-status 0 :foreign 0))
        \\(roundtrip
        \\  (rung1 :ok true :sha256 "{s}")
        \\  (rung2 :ok true))
        \\(write :format0 true :sha256 "{s}" :bytes {d} :tracks 1 :events 4)
        \\
    , .{
        file.bytes.len,
        try testDigest(a, file.bytes),
        try testDigest(a, file.bytes),
        try testDigest(a, merged.bytes),
        merged.bytes.len,
    });
    try t_.expectEqualStrings(want, text);
}

test "corpus render: an IT case — the read echo and the walk's row map" {
    var arena = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const gpa = t_.allocator;

    // `walk-constant`'s module: four rows of six ticks, one note.
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    b.setTitle("render");
    try b.addOrder(0);
    const pat = try b.addPattern(4);
    pat.at(0, 0).* = .{ .note = 60 };
    var m = b.finish();
    defer m.deinit();
    // `:loose` because a four-row pattern is under IT 2.14's floor of
    // 32: the corners are about rows, and the reader honours them.
    var file = try itf.write.write(gpa, &m, null, .{ .loose = true });
    defer file.deinit();

    const text = try testRender(a, .{ .file = "song.it", .bytes = file.bytes, .kind = .it }, &.{
        .read,
        .{ .walk = 1 << 20 },
    });

    var read_back = try itf.read.read(gpa, file.bytes);
    defer read_back.deinit();
    const rows_diag = read_back.diags.items()[0];

    const want = try std.fmt.allocPrint(a,
        \\; tempura corpus golden — GENERATED by `zig build corpus -- --update`; do not hand-edit.
        \\(fixture :file "song.it" :bytes {d} :sha256 "{s}")
        \\(read
        \\  (it :title "render" :speed 6 :tempo 125 :orders 2 :patterns 1 :instruments 0 :samples 0 :message-len 0 :tmpu false)
        \\  (diag :code {d} :severity warning :start {d} :end {d} :message "pattern 0 has 4 rows, outside IT's strict 32–200"))
        \\(walk :max-rows 1048576
        \\  (row :order 0 :pattern 0 :row 0 :start 0 :ticks 6)
        \\  (row :order 0 :pattern 0 :row 1 :start 6 :ticks 6)
        \\  (row :order 0 :pattern 0 :row 2 :start 12 :ticks 6)
        \\  (row :order 0 :pattern 0 :row 3 :start 18 :ticks 6)
        \\  (segment :tick 0 :tempo 125)
        \\  (onset :ch 0 :tick 0 :note 60)
        \\  (total :ticks 24 :loop-row 0))
        \\
    , .{
        file.bytes.len,
        try testDigest(a, file.bytes),
        @intFromEnum(Diag.Code.it_pattern_rows_out_of_range),
        rows_diag.span.start,
        rows_diag.span.end,
    });
    try t_.expectEqualStrings(want, text);
}

test "corpus render: diagnostics carry the ordinal, the span and an escaped message" {
    var arena = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    var diags: Diag.List = .init(t_.allocator);
    defer diags.deinit();
    try diags.add(.walk_runaway, .err, .{ .start = 1, .end = 2 }, "gave up", .{});
    try diags.add(.it_command_unknown, .warning, .{ .start = 3, .end = 5 }, "a \"quoted\" \\ word", .{});
    try diags.add(.smpte_tempo_ignored, .info, .{ .start = 0, .end = 0 }, "kept, not believed", .{});

    var aw: Io.Writer.Allocating = .init(a);
    try t_.expect(try renderDiags(&aw.writer, "  ", &diags, .{ .out = null, .name = "test" }));

    // The CODE is the numeric ordinal, not the name: the ordinal is the
    // wire, and `zig build audit-diagnostics` is what keeps every name
    // in a test. A quote and a backslash are escaped; nothing else is.
    const want = try std.fmt.allocPrint(a,
        \\
        \\  (diag :code {d} :severity error :start 1 :end 2 :message "gave up")
        \\  (diag :code {d} :severity warning :start 3 :end 5 :message "a \"quoted\" \\ word")
        \\  (diag :code {d} :severity info :start 0 :end 0 :message "kept, not believed")
    , .{
        @intFromEnum(Diag.Code.walk_runaway),
        @intFromEnum(Diag.Code.it_command_unknown),
        @intFromEnum(Diag.Code.smpte_tempo_ignored),
    });
    try t_.expectEqualStrings(want, aw.written());
}

test "corpus render: a walk longer than the echo cap says how much it left out" {
    var arena = std.heap.ArenaAllocator.init(t_.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const gpa = t_.allocator;

    // 22 orders of one 200-row pattern, a note on every row: 4400 rows
    // played and 4400 onsets, 304 of each past the 4096 the echo
    // carries. A golden nobody can read is not evidence.
    var b: itf.Builder = .init(gpa);
    errdefer b.deinit();
    for (0..22) |_| try b.addOrder(0);
    const pat = try b.addPattern(200);
    for (0..200) |row| pat.at(row, 0).* = .{ .note = 60 };
    var m = b.finish();
    defer m.deinit();

    var aw: Io.Writer.Allocating = .init(a);
    try t_.expect(try renderWalk(gpa, &aw.writer, &m, 1 << 20, .{ .out = null, .name = "test" }));
    const text = aw.written();

    try t_.expect(std.mem.indexOf(u8, text, "(row :order 0 :pattern 0 :row 0 :start 0 :ticks 6)") != null);
    try t_.expect(std.mem.indexOf(u8, text, "(rows-elided 304)") != null);
    try t_.expect(std.mem.indexOf(u8, text, "(onsets-elided 304)") != null);
    try t_.expect(std.mem.indexOf(u8, text, "(total :ticks 26400 :loop-row 0)") != null);
    // 4096 of each echoed and not one more.
    try t_.expectEqual(@as(usize, 4096), std.mem.count(u8, text, "\n  (row :"));
    try t_.expectEqual(@as(usize, 4096), std.mem.count(u8, text, "\n  (onset :"));
}
